"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8956],{18956:a=>{a.exports=JSON.parse('{"slug":"yandex-data-centry-ataki-sboi-oblako","locale":"zh","title":"4天内3座Yandex数据中心遭袭，数十服务中断","description":"2026年十月8日至11日，Yandex的3座、合计最高115MW数据中心受袭。哪些服务受影响，为何恢复昂贵。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年十月8日，无人机袭击及火灾使梁赞州萨索沃Yandex数据中心停运，约12MW。十月9日，卡卢加63MW、超过3800机架中心受损；十月11日，弗拉基米尔约40MW中心完全停止。合计最高115MW，约俄罗斯总容量1.8GW的6%。弗拉基米尔无人伤亡。Yandex未披露损失及设备维修期限。"},{"id":"b002","kind":"paragraph","text":"故障影响Yandex Go、Pay、邮件、地图和外卖；哈萨克斯坦、白俄罗斯、亚美尼亚和塞尔维亚也叫不到车。租用Yandex Cloud的CIAN、数家开发商网站及Astral电子文档系统同样中断。十月11日称服务逐渐恢复，但十月12日金融科技负责人德米特里\xb7皮罗戈夫表示仍无法给Pay全面恢复日期。"},{"id":"b003","kind":"paragraph","text":"云即租他人服务器，企业按容量付费，不自建中心，正常时方便。类似全家钱都在一张银行卡，卡一冻结就不能支付。保护方法是在另一站点留副本，即冗余；需付2套而非1套资源，故很多企业节省此项。Yandex Cloud分独立中心可用区，但4区中2区——弗拉基米尔和萨索沃——失效。公司称剩余区不稳定，建议客户准备替代站点，并与VK Cloud、Selectel、K2Cloud协商快速接纳数据及服务。"},{"id":"b004","kind":"paragraph","text":"恢复昂贵。全球服务器和神经网络加速器因AI需求短缺，市场估交期从2–3到6个月。Mobile Research Group的穆尔塔津称，俄罗斯设备数日涨10–15%。RUVDS的尼基塔\xb7察普林称部分中心已加固防护，费用可能进入客户价格。Strategy Partners的谢尔盖\xb7库德里亚绍夫估Yandex Cloud收入约30十亿卢布，占集团2–4%。云本身不大，但主要服务也运行在同样中心。"},{"id":"b005","kind":"paragraph","text":"普通用户直接遇到叫车或支付不可用；间接传导更长。如果设备和防护涨价推高云费，租云企业会把部分成本加到服务售价，幅度尚无人估计。"},{"id":"b006","kind":"paragraph","text":"企业选择困难：现在增备用站点或换供应商要花钱，而设备短缺；留单一供应商更便宜，但下次故障再停销售。Yandex何时恢复旧容量仍未知。"},{"id":"b007","kind":"heading","text":"Yandex哪些中心在2026年十月遭袭？"},{"id":"b008","kind":"paragraph","text":"十月8日萨索沃约12MW停运；十月9日卡卢加63MW受损；十月11日弗拉基米尔约40MW停止。"},{"id":"b009","kind":"heading","text":"袭击导致哪些服务不可用？"},{"id":"b010","kind":"paragraph","text":"Yandex Go、Pay、邮件、地图和外卖，以及CIAN、Astral等租云企业。哈萨克斯坦、白俄罗斯、亚美尼亚和塞尔维亚也无法叫车。"},{"id":"b011","kind":"heading","text":"服务何时恢复？"},{"id":"b012","kind":"paragraph","text":"公司未给精确日期。服务渐恢复，但替换设备需2到6个月。十月12日Pay仍无法给恢复时间。"}],"sources":[{"label":"Yandex数据中心受袭引发连锁故障，谁受影响","url":"https://thebell.io/ataka-na-data-tsentr-yandeksa-vyzvala-tsepnuyu-reaktsiyu-sboev-kto-postradal"},{"label":"无人机袭击导致Yandex中断及云价格上涨风险","url":"https://www.kommersant.ru/doc/9024163"},{"label":"无人机一周内袭击第三座Yandex中心","url":"https://ru.themoscowtimes.com/2026/10/11/droni-atakovali-tretii-data-tsentr-yandeksa-zanedelyu-a208309"},{"label":"弗拉基米尔Yandex数据中心袭击详情","url":"https://www.fontanka.ru/2026/10/11/76693363/"},{"label":"专家讨论数据中心袭击后果","url":"https://www.fontanka.ru/2026/10/11/76693413/"},{"label":"Yandex再故障：弗拉基米尔停运，ru-central1-a区不可用","url":"https://www.comss.ru/page.php?id=22366"},{"label":"Yandex Pay无法给恢复日期","url":"https://vz.ru/news/2026/10/12/1461835.html"}],"sourceBodySha256":"90f104461afebdbd416e2a7cbc14c93eb9a1629170e459918558786e22c1b0b1"}')}}]);